use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance, ItemVerdict};

struct Node;

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must-read",
        Importance::WorthALook => "worth a look",
        Importance::Skip => "skip",
    }
}

fn importance_rank(i: Importance) -> u8 {
    match i {
        Importance::MustRead => 0,
        Importance::WorthALook => 1,
        Importance::Skip => 2,
    }
}

/// Collapse whitespace and newlines so feed-supplied text cannot reshape the
/// message layout, and bound its length.
fn clean(s: &str, max_chars: usize) -> String {
    let mut out = String::new();
    let mut count = 0usize;
    let mut last_space = false;
    for ch in s.chars() {
        let c = if ch.is_whitespace() || ch.is_control() { ' ' } else { ch };
        if c == ' ' {
            if last_space || out.is_empty() {
                continue;
            }
            last_space = true;
        } else {
            last_space = false;
        }
        if count >= max_chars {
            out.push('…');
            return out.trim_end().to_string();
        }
        out.push(c);
        count += 1;
    }
    out.trim_end().to_string()
}

fn render_entry(out: &mut String, e: &ItemVerdict) {
    out.push_str("- [");
    out.push_str(importance_label(e.importance));
    out.push_str(" / ");
    out.push_str(category_label(e.category));
    out.push_str("] ");
    let title = clean(&e.title, 200);
    out.push_str(if title.is_empty() { "(untitled)" } else { &title });
    let feed = clean(&e.feed, 120);
    if !feed.is_empty() {
        out.push_str(" (");
        out.push_str(&feed);
        out.push(')');
    }
    out.push('\n');
    let link = clean(&e.link, 500);
    if !link.is_empty() {
        out.push_str("  ");
        out.push_str(&link);
        out.push('\n');
    }
    let summary = clean(&e.summary, 800);
    if !summary.is_empty() {
        out.push_str("  ");
        out.push_str(&summary);
        out.push('\n');
    }
}

fn render(d: &Digest) -> String {
    let mut msg = String::new();
    msg.push_str("Digest for ");
    let date = clean(&d.date, 64);
    msg.push_str(if date.is_empty() { "(undated)" } else { &date });
    msg.push('\n');

    let overview = clean(&d.overview, 2000);
    if !overview.is_empty() {
        msg.push('\n');
        msg.push_str(&overview);
        msg.push('\n');
    }

    let mut entries: Vec<&ItemVerdict> = d.entries.iter().filter(|e| e.kept).collect();
    if entries.is_empty() {
        entries = d.entries.iter().collect();
    }
    entries.sort_by_key(|e| importance_rank(e.importance));

    msg.push('\n');
    if entries.is_empty() {
        msg.push_str("No items made the digest this run.\n");
    } else {
        for e in entries {
            render_entry(&mut msg, e);
        }
    }

    msg.push_str(&format!("\n{} item(s) considered.", d.considered.len()));
    msg
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);
        let mut published = notifier::notify(&message);
        if !published {
            // One retry for a transient refusal by the channel.
            published = notifier::notify(&message);
        }
        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
